import time,signal
started=time.monotonic();deadline=float(started+20.0)
class Deadline(BaseException):pass
def expired(*_):raise Deadline()
signal.signal(signal.SIGALRM,expired);signal.setitimer(signal.ITIMER_REAL,20.0)
import base64,hashlib,json,os,platform,types
try:
 assert os.getuid()==os.geteuid()==os.getgid()==os.getegid()==0 and platform.system()=='Linux' and platform.machine()=='x86_64'
 p=json.loads(base64.b64decode('',validate=True))
 decode=lambda x:base64.b64decode(x,validate=True)
 data={k:{n:decode(v) for n,v in p['old'][k].items()} for k in ('base','frozen','payload','dual','recovery_raws')}
 data.update(p['scalar'])
 for k in ('recovery_boot_raw','closeout_raw','capsule'):data[k]=decode(p['old'][k])
 raw=decode(p['runtime']);assert hashlib.sha256(raw).hexdigest()==p['runtimeSha']
 m=types.ModuleType('fixed_periodic_runtime');exec(compile(raw,'<fixed-periodic-runtime>','exec'),m.__dict__)
 old=data.pop('capsule')
 body=m.execute(data,old,{k:decode(v) for k,v in p['periodic'].items()},p['expected'],decode(p['state']),p['live'],deadline,p['runtimeSha'])
except BaseException as exc:
 body={'state':'UNCONFIRMED','normalProbeVerified':False,'messagesSent':False,'notificationsEnabled':False,'failureClass':type(exc).__name__ if type(exc).__name__ in ('Deadline','ValueError','PermissionError','FileNotFoundError') else 'OtherException'}
finally:signal.setitimer(signal.ITIMER_REAL,0)
print(json.dumps(body,sort_keys=True,separators=(',',':'),allow_nan=False))
raise SystemExit(0 if body.get('state')=='COMMITTED' else 2)
